<section class="single-herbs-guide__section" aria-labelledby="topic-twenty-foundations"><h4 id="topic-twenty-foundations"><?php echo s($bleedtext('Regulate Blood and stop bleeding: general introduction','Regular Sangre y detener sangrado: introducción general'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($bleedtext('Board questions require two decisions: where is the bleeding, and why is it happening? Choose the mechanism only after identifying Heat, Cold, deficiency, trauma or stasis.','Las preguntas Board exigen dos decisiones: ¿dónde sangra y por qué? Elige mecanismo solo después de identificar Calor, Frío, deficiencia, trauma o estasis.'));?></p><div class="single-herbs-guide__decision"><div><strong><?php echo s($bleedtext('Trauma + stasis','Trauma + estasis'));?></strong><span>San Qi · Pu Huang</span></div><div><strong><?php echo s($bleedtext('Lung / Upper Jiao','Pulmón / Jiao Superior'));?></strong><span>Bai Ji · Ce Bai Ye · Bai Mao Gen</span></div><div><strong><?php echo s($bleedtext('Intestine / Lower Jiao','Intestino / Jiao Inferior'));?></strong><span>Di Yu · Huai Mi</span></div><div><strong><?php echo s($bleedtext('Cold uterus','Útero frío'));?></strong><span>Ai Ye</span></div></div><aside class="single-herbs-guide__memory-path"><p class="single-herbs-guide__memory-line"><?php echo s($bleedtext('Enter the hospital with four hemostasis rooms.','Entra al hospital con cuatro salas de hemostasia.'));?></p><p><?php echo s($bleedtext('San Qi is the trauma medic; Pu Huang has raw/charred switches. Bai Ji seals tissue, Xian He Cao closes every leak, and Ce Bai Ye clears Lung mucus. Ai Ye warms the womb. Di Yu works downstairs on bowel bleeding and burns. Bai Mao Gen cools Lung and urine while restoring fluids. Huai Mi closes hemorrhoids and shades Liver-Heat eyes.','San Qi es paramédico de trauma; Pu Huang tiene interruptores crudo/carbonizado. Bai Ji sella tejido, Xian He Cao cierra toda fuga y Ce Bai Ye limpia moco pulmonar. Ai Ye calienta útero. Di Yu trabaja abajo con intestino y quemaduras. Bai Mao Gen enfría Pulmón y orina mientras repone líquidos. Huai Mi cierra hemorroides y sombrea ojos por Calor de Hígado.'));?></p></aside><p class="single-herbs-guide__safety"><strong><?php echo s($bleedtext('Emergency boundary:','Límite de emergencia:'));?></strong> <?php echo s($bleedtext('Heavy, recurrent, unexplained, internal, pregnancy-related or trauma-related bleeding requires urgent medical assessment. This guide is not first-aid or prescribing instruction.','Sangrado abundante, recurrente, inexplicado, interno, relacionado con embarazo o trauma requiere evaluación urgente. Esta guía no es instrucción de primeros auxilios ni prescripción.'));?></p><ol class="single-herbs-guide__category-herbs"><?php foreach($bleedherbs as $h):?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($h['name']);?></strong><em><?php echo s($h['latin']);?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($bleedtext('Current category list','Lista vigente de la categoría'));?></span></div><p><?php echo s($h['identity']);?></p></li><?php endforeach;?></ol></section>
<section class="single-herbs-guide__section" aria-labelledby="topic-twenty-yang"><h4 id="topic-twenty-yang"><?php echo s($bleedtext('Yang comparative fingerprints','Huellas comparativas de Yang'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($bleedtext('Relative study indices—not doses or clinical percentages. Only exact current-list entries are graphed; Huai Hua is not silently substituted for Huai Mi.','Índices relativos de estudio—no dosis ni porcentajes clínicos. Solo se grafican entradas exactas de la lista; Huai Hua no se sustituye silenciosamente por Huai Mi.'));?></p><div class="single-herbs-guide__yang-charts"><?php foreach($bleedcharts as $chart):?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart[0]);?></h5><small><?php echo s($chart[1]);?></small><?php foreach($chart[2] as $name=>$value):?><div class="single-herbs-guide__yang-bar"><span><?php echo s($name);?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo(int)$value;?>%"></span></span><b><?php echo(int)$value;?></b></div><?php endforeach;?></article><?php endforeach;?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($bleedtext('Additional unique values:','Valores únicos adicionales:'));?></strong> <?php echo s($bleedtext('Ai Ye = 80 among warm hemostatics; Xian He Cao = 100 among astringent hemostatics; Bai Mao Gen = 80 for urinary bleeding. Other herbs in Yang’s complete figures are outside this current list.','Ai Ye = 80 entre hemostáticas tibias; Xian He Cao = 100 entre hemostáticas astringentes; Bai Mao Gen = 80 para sangrado urinario. Las demás hierbas de las figuras completas están fuera de esta lista.'));?></p></section>
<section class="single-herbs-guide__section" aria-labelledby="topic-twenty-profiles"><h4 id="topic-twenty-profiles"><?php echo s($bleedtext('Individual herb profiles','Perfiles individuales de las hierbas'));?></h4><div class="single-herbs-guide__profiles"><?php foreach($bleedherbs as $h):?><details class="single-herbs-guide__profile"<?php echo $h['name']==='San Qi'?' open':'';?>><summary><span class="single-herbs-guide__profile-name"><?php echo s($h['name']);?></span><span class="single-herbs-guide__profile-latin"><?php echo s($h['latin']);?></span><span class="single-herbs-guide__profile-meta"><?php echo s($h['properties']);?> · <?php echo s($h['channels']);?></span></summary><div class="single-herbs-guide__profile-body"><dl><dt><?php echo s($bleedtext('Study dose','Dosis de estudio'));?></dt><dd><?php echo s($h['dose']);?></dd><dt><?php echo s($bleedtext('Identity','Identidad'));?></dt><dd><?php echo s($h['identity']);?></dd><dt><?php echo s($bleedtext('Exam clue','Pista de examen'));?></dt><dd><?php echo s($h['clue']);?></dd><dt><?php echo s($bleedtext('Memory','Memoria'));?></dt><dd class="single-herbs-guide__profile-memory"><?php echo s($h['memory']);?></dd><dt><?php echo s($bleedtext('Unique fingerprint','Huella única'));?></dt><dd><?php echo s($h['unique']);?></dd><dt><?php echo s($bleedtext('Formula boundary','Límite de fórmulas'));?></dt><dd class="single-herbs-guide__profile-formulas"><?php echo s($bleedtext('No chief or co-chief role in the current 63-formula Board roster.','No tiene papel principal ni coprincipal en el listado Board vigente de 63 fórmulas.'));?></dd><dt><?php echo s($bleedtext('Safety','Seguridad'));?></dt><dd class="single-herbs-guide__profile-safety"><?php echo s($h['caution']);?></dd></dl></div></details><?php endforeach;?></div></section>
<section class="single-herbs-guide__section" aria-labelledby="topic-twenty-comparisons"><h4 id="topic-twenty-comparisons"><?php echo s($bleedtext('High-yield comparisons','Comparaciones de alto rendimiento'));?></h4><div class="single-herbs-guide__comparisons"><?php foreach($bleedcomparisons as $c):?><?php $url=new moodle_url($ises?$c[1]:$c[0],['from'=>'single-herbs','focus'=>(string)$selected['number']]);?><a class="single-herbs-guide__comparison" href="<?php echo $url->out(false);?>"><strong><?php echo s($c[2]);?></strong><span><?php echo s($c[3]);?></span><small><?php echo s($bleedtext('Open full comparison →','Abrir comparación completa →'));?></small></a><?php endforeach;?></div></section>
<section class="single-herbs-guide__section" aria-labelledby="topic-twenty-questions"><h4 id="topic-twenty-questions"><?php echo s($bleedtext('Yang questions shown in full','Preguntas de Yang mostradas completas'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($bleedtext('All eight chapter 12 questions appear in full. Herbs outside the current list are identified on the answer side.','Las ocho preguntas del capítulo 12 aparecen completas. Las hierbas fuera de lista se identifican en la respuesta.'));?></p><div class="single-herbs-guide__yang-deck" data-yang-deck data-card-label="<?php echo s($bleedtext('Card','Tarjeta'));?>" data-of-label="<?php echo s($bleedtext('of','de'));?>"><?php foreach($bleedquestions as $i=>$q):?><article class="single-herbs-guide__yang-card<?php echo $i===0?' is-active':'';?>" data-yang-card aria-hidden="<?php echo $i===0?'false':'true';?>"><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--front"><span class="single-herbs-guide__yang-label"><?php echo s($bleedtext('Question','Pregunta'));?> <?php echo$i+1;?> <?php echo s($bleedtext('of','de'));?> <?php echo count($bleedquestions);?> · Yang, <?php echo s($bleedtext('Chapter','capítulo'));?> 12</span><p class="single-herbs-guide__yang-question"><?php echo s($q[0]);?></p></div><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--back"><span class="single-herbs-guide__yang-label"><?php echo s($bleedtext('Answer','Respuesta'));?> <?php echo$i+1;?></span><p class="single-herbs-guide__yang-answer"><?php echo s($q[1]);?></p></div></article><?php endforeach;?><div class="single-herbs-guide__yang-controls"><button class="single-herbs-guide__yang-control" type="button" data-yang-prev>← <?php echo s($bleedtext('Previous','Anterior'));?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--flip" type="button" data-yang-flip data-show-label="<?php echo s($bleedtext('Show answer','Mostrar respuesta'));?>" data-hide-label="<?php echo s($bleedtext('Show question','Mostrar pregunta'));?>"><?php echo s($bleedtext('Show answer','Mostrar respuesta'));?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--next" type="button" data-yang-next><?php echo s($bleedtext('Next','Siguiente'));?> →</button></div><p class="single-herbs-guide__yang-progress" data-yang-progress><?php echo s($bleedtext('Card','Tarjeta'));?> 1 <?php echo s($bleedtext('of','de'));?> <?php echo count($bleedquestions);?></p></div></section>
